import type { CityId } from './cities'

export type NeighborhoodBounds = { name: string; bbox: number[] }

// Generated by scripts/build-streets.ts from each city's official boundaries (see cities.ts).
const files = import.meta.glob<NeighborhoodBounds[]>('./neighborhoods.*.json', { eager: true, import: 'default' })

export const NEIGHBORHOODS = Object.fromEntries(
  Object.entries(files).map(([file, hoods]) => [file.match(/neighborhoods\.(\w+)\.json$/)![1], hoods]),
) as Record<CityId, NeighborhoodBounds[]>
